#include <BLEDevice.h>
#include <BLEServer.h>
#include <BLEUtils.h>

#define SVC "6E400001-B5A3-F393-E0A9-E50E24DCCA9E"
#define RX "6E400002-B5A3-F393-E0A9-E50E24DCCA9E"
#define TX "6E400003-B5A3-F393-E0A9-E50E24DCCA9E"

class RxCB : public BLECharacteristicCallbacks {
  void onWrite(BLECharacteristic* c) override {
    Serial.println(c->getValue().c_str());
  }
};

void setup() {
  Serial.begin(115200);
  BLEDevice::init("{{device_name}}");
  auto srv = BLEDevice::createServer();
  auto svc = srv->createService(SVC);
  auto rx = svc->createCharacteristic(RX, BLECharacteristic::PROPERTY_WRITE);
  rx->setCallbacks(new RxCB());
  svc->createCharacteristic(TX, BLECharacteristic::PROPERTY_NOTIFY);
  svc->start();
  BLEDevice::getAdvertising()->start();
}

void loop() { delay(1000); }
